//! Reference normal/depth pass, reusing camera-v2 view/project/near clip.
use super::primitives::Geometry;
use super::mesh::Mesh;
use crate::{effects::Frame,camera_projection::{Camera,Vertex,clip}};
use serde::{Serialize,Deserialize};
#[derive(Clone,Copy,Debug,Serialize,Deserialize)]#[serde(rename_all="snake_case")]pub enum Shading{Normal,Depth,Wireframe}
pub struct Output{pub frame:Frame,pub depth:Vec<f64>,pub covered:usize,pub clipped_triangles:usize}
/// Normals are world-space. Render geometry in world coordinates; camera has
/// positive-Z view convention. No material lighting/textures/alpha composition.
pub fn render(g:&Geometry,camera:&Camera,w:usize,h:usize,mode:Shading,depth_range:[f64;2])->Result<Output,String>{g.verify()?;let normals:Vec<[f64;3]>=g.vertices.iter().map(|v|v.normal.map(|x|x as f64)).collect();render_mesh(&g.mesh(),&normals,camera,w,h,mode,depth_range)}
/// Raw-mesh variant of `render`: caller supplies one world-space normal per position (e.g. averaged
/// face normals of a subdivided mesh that has no primitive analytic counts to verify against).
pub fn render_mesh(mesh:&Mesh,normals:&[[f64;3]],camera:&Camera,w:usize,h:usize,mode:Shading,depth_range:[f64;2])->Result<Output,String>{mesh.validate()?;if normals.len()!=mesh.positions.len(){return Err("one normal per position required".into());}camera.validate()?;if w==0||h==0||w>4096||h>4096||depth_range.iter().any(|v|!v.is_finite())||depth_range[0]<=0.0||depth_range[1]<=depth_range[0]{return Err("target1..4096 and0<depth_near<depth_far required".into());}let mut frame=Frame::try_new(w,h)?;let mut depth=vec![f64::INFINITY;w*h];let projection=Camera{eye:[0.;3],pan:0.,tilt:0.,roll:0.,..*camera};let mut clipped_triangles=0;
 let edge=|a:[f64;3],b:[f64;3],x:f64,y:f64|(b[0]-a[0])*(y-a[1])-(b[1]-a[1])*(x-a[0]);
 for indices in &mesh.indices{crate::guard::check();let mut vertices=Vec::with_capacity(3);for id in indices{let i=*id as usize;vertices.push(Vertex{position:camera.view(mesh.positions[i])?,attributes:normals[i].to_vec()});}let tri:[Vertex;3]=vertices.try_into().map_err(|_|"triangle conversion")?;let triangles=clip(tri,camera.near)?;clipped_triangles+=triangles.len();for t in triangles{let mut projected=[[0.;3];3];for i in 0..3{projected[i]=projection.project(t[i].position,w as u32,h as u32)?.ok_or("clipped vertex failed camera projection")?;}let area=edge(projected[0],projected[1],projected[2][0],projected[2][1]);if !area.is_finite(){return Err("projected triangle area overflow".into());}if area==0.0{continue;}
 let bounds=|axis:usize,limit:usize|{let lo=projected.iter().map(|p|p[axis]).fold(f64::INFINITY,f64::min).floor().clamp(0.,limit as f64) as usize;let hi=projected.iter().map(|p|p[axis]).fold(f64::NEG_INFINITY,f64::max).ceil().clamp(0.,limit as f64) as usize;(lo,hi)};let (x0,x1)=bounds(0,w);let(y0,y1)=bounds(1,h);
 for y in y0..y1{crate::guard::check();for x in x0..x1{let(sx,sy)=(x as f64+0.5,y as f64+0.5);let b=[edge(projected[1],projected[2],sx,sy)/area,edge(projected[2],projected[0],sx,sy)/area,edge(projected[0],projected[1],sx,sy)/area];if b.iter().any(|v|*v<0.){continue;}let inv_z=(0..3).map(|i|b[i]/projected[i][2]).sum::<f64>();if !inv_z.is_finite()||inv_z<=0.{return Err("inverse depth invalid".into());}let z=1.0/inv_z;let id=y*w+x;if !z.is_finite(){return Err("depth overflow".into());}let(color,zw)=match mode{Shading::Depth=>{let v=((z-depth_range[0])/(depth_range[1]-depth_range[0])).clamp(0.,1.);([v;3],z)},Shading::Wireframe=>{let distance=(0..3).map(|i|{let a=projected[(i+1)%3];let c=projected[(i+2)%3];let length=(c[0]-a[0]).hypot(c[1]-a[1]);if length==0.0{f64::INFINITY}else{b[i].abs()*area.abs()/length}}).fold(f64::INFINITY,f64::min);if distance<=1.0{([0.95;3],z*(1.0-1e-6))}else{([0.04;3],z)}},Shading::Normal=>{let n:[f64;3]=std::array::from_fn(|j|(0..3).map(|i|b[i]*t[i].attributes[j]/projected[i][2]).sum::<f64>()/inv_z);let len=n[0].hypot(n[1]).hypot(n[2]);if !len.is_finite()||len==0.{return Err("interpolated normal singular".into());}(n.map(|v|0.5+0.5*v/len),z)}};if zw>=depth[id]{continue;}depth[id]=zw;for j in 0..3{frame.d[id*4+j]=color[j] as f32;}frame.d[id*4+3]=1.;}}
 }}let covered=depth.iter().filter(|v|v.is_finite()).count();Ok(Output{frame,depth,covered,clipped_triangles})}
#[cfg(test)]mod tests{
 use super::*;use crate::threed::primitives::{generate,Primitive};
 fn camera()->Camera{Camera{eye:[2.4,1.9,-3.4],pan:324.79,tilt:24.55,roll:0.,sensor_height:24.,focal_length:35.,near:0.1}}
 #[test]fn camera_pass_invariants(){let g=generate(&Primitive::Sphere{radius:1.,longitude_slices:16,latitude_slices:8}).unwrap();for mode in [Shading::Normal,Shading::Depth,Shading::Wireframe]{let o=render(&g,&camera(),128,72,mode,[2.,6.]).unwrap();assert!(o.covered>0&&o.covered<128*72);assert!(o.frame.d.iter().all(|v|v.is_finite()&&(0.0..=1.0).contains(v)));assert!(o.depth.iter().filter(|v|v.is_finite()).all(|v|*v>=0.1));}}
 #[test]fn wireframe_depth_bias_order_independent(){let mut g=generate(&Primitive::Cube{size:[1.5;3],subdivisions:2}).unwrap();let a=render(&g,&camera(),128,72,Shading::Wireframe,[2.,6.]).unwrap();g.indices.reverse();let b=render(&g,&camera(),128,72,Shading::Wireframe,[2.,6.]).unwrap();for (x,y) in a.frame.d.iter().zip(&b.frame.d){assert!((x-y).abs()<1e-6,"equal-depth edge/surface ties resolve deterministically with edge bias");}}
 #[test]#[ignore="1080p wireframe normal contact sources after library gates"]
 fn render_primitive_contact_sources(){use std::io::Write;let dir=std::env::var("KIMO_PRIMITIVE_FRAMES").expect("output directory");std::fs::create_dir_all(&dir).unwrap();let p=[Primitive::Cube{size:[1.5;3],subdivisions:4},Primitive::Sphere{radius:1.,longitude_slices:32,latitude_slices:16},Primitive::Torus{major_radius:0.8,minor_radius:0.3,radial_segments:32,tubular_segments:16}];for(name,p)in ["cube","sphere","torus"].iter().zip(p){let g=generate(&p).unwrap();for(label,mode)in [("wire",Shading::Wireframe),("normal",Shading::Normal),("depth",Shading::Depth)]{let o=render(&g,&camera(),1920,1080,mode,[2.5,5.5]).unwrap();let path=format!("{dir}/{name}-{label}.png");let mut c=std::process::Command::new("ffmpeg").args(["-v","error","-y","-f","rawvideo","-pix_fmt","rgba","-s","1920x1080","-i","-","-frames:v","1",&path]).stdin(std::process::Stdio::piped()).spawn().unwrap();c.stdin.take().unwrap().write_all(&crate::render::to_rgba8(&o.frame)).unwrap();assert!(c.wait().unwrap().success());}}}
}
